import { S3Client, PutObjectCommand, HeadBucketCommand } from '@aws-sdk/client-s3';
import { readFileSync } from 'fs';

const key = process.env.AWS_ACCESS_KEY_ID || '';
const secret = process.env.AWS_SECRET_ACCESS_KEY || '';
const region = process.env.AWS_REGION || 'us-east-1';

console.log('KEY:', key ? key.substring(0,12)+'...' : 'MISSING');
console.log('SECRET:', secret ? 'set('+secret.length+')' : 'MISSING');

if (!key || !secret) {
  console.log('No env creds. Trying default credential chain...');
}

// Try without explicit creds - SDK will use default chain
const s3 = new S3Client({ 
  region,
  ...(key && secret ? { 
    credentials: { accessKeyId: key, secretAccessKey: secret } 
  } : {})
});

try {
  await s3.send(new HeadBucketCommand({ Bucket: 'ivxholding.com' }));
  console.log('Bucket accessible!');

  const apk = readFileSync('/home/user/rork-app/expo/android/app/build/outputs/apk/release/app-release.apk');
  console.log('APK size:', (apk.length/(1024*1024)).toFixed(1), 'MB');

  const cmd = new PutObjectCommand({
    Bucket: 'ivxholding.com',
    Key: 'apk/ivx-holdings-v1.4.5.apk',
    Body: apk,
    ContentType: 'application/vnd.android.package-archive',
    ContentDisposition: 'attachment; filename=\"ivx-holdings-v1.4.5.apk\"',
    CacheControl: 'no-cache, no-store, must-revalidate',
  });
  await s3.send(cmd);
  console.log('Upload SUCCESS!');
  console.log('Download URL: https://ivxholding.com/apk/ivx-holdings-v1.4.5.apk');
} catch (e) {
  console.error('Error:', e.message || e);
}
" 2>&1

